add_filter( 'body_class', 'perfectpixel_subcategory_body_class' );

function perfectpixel_subcategory_body_class( $classes ) {
	if ( ! function_exists( 'is_product_category' ) || ! is_product_category() ) {
		return $classes;
	}
	$ancestors = get_ancestors( get_queried_object_id(), 'product_cat', 'taxonomy' );
	if ( $ancestors ) {
		$classes[] = 'product-subcategory';
		foreach ( $ancestors as $ancestor_id ) {
			$term = get_term( $ancestor_id, 'product_cat' );
			if ( $term && ! is_wp_error( $term ) ) {
				$classes[] = 'product-cat-parent-' . sanitize_html_class( $term->slug );
			}
		}
	}
	return $classes;
}
